<?php
use App\Http\Controllers\Auth\OtpLoginController;use App\Http\Controllers\DashboardController;use App\Http\Controllers\PayrollController;use App\Http\Controllers\ProjectController;use App\Http\Controllers\UserController;use App\Http\Controllers\PeriodController;use App\Http\Controllers\PayrollImportController;use App\Http\Controllers\ApprovalController;use App\Http\Controllers\ExportController;use Illuminate\Support\Facades\Route;
Route::middleware('guest')->group(function(){Route::get('/login',[OtpLoginController::class,'create'])->name('login');Route::post('/login/password',[OtpLoginController::class,'password'])->middleware('throttle:10,1')->name('login.password');Route::post('/login/send',[OtpLoginController::class,'send'])->middleware('throttle:5,1')->name('login.send');Route::get('/login/verify',[OtpLoginController::class,'verifyForm'])->name('login.verify');Route::post('/login/verify',[OtpLoginController::class,'verify'])->middleware('throttle:10,1')->name('login.verify.submit');});
Route::middleware('auth')->group(function(){Route::post('/logout',[OtpLoginController::class,'destroy'])->name('logout');Route::get('/',DashboardController::class)->name('dashboard');Route::middleware('hr.manager')->group(function(){Route::get('/projects',[ProjectController::class,'index'])->name('projects.index');Route::post('/projects',[ProjectController::class,'store'])->name('projects.store');Route::delete('/projects/{project}',[ProjectController::class,'destroy'])->name('projects.destroy');Route::get('/users',[UserController::class,'index'])->name('users.index');Route::post('/users',[UserController::class,'store'])->name('users.store');});Route::middleware('hr.staff')->group(function(){Route::get('/periods',[PeriodController::class,'index'])->name('periods.index');Route::post('/periods',[PeriodController::class,'store'])->name('periods.store');Route::get('/periods/{period}',[PeriodController::class,'show'])->name('periods.show');Route::post('/periods/{period}/columns',[PeriodController::class,'addColumn'])->name('periods.columns.store');Route::delete('/periods/{period}/columns/{column}',[PeriodController::class,'deleteColumn'])->name('periods.columns.destroy');Route::post('/periods/{period}/publish',[PeriodController::class,'publish'])->name('periods.publish');Route::post('/periods/{period}/import',[PayrollImportController::class,'store'])->name('periods.import');});Route::get('/payroll',[PayrollController::class,'index'])->name('payroll.index');Route::get('/payroll/{sheet}',[PayrollController::class,'show'])->name('payroll.show');Route::patch('/payroll/{sheet}/cell',[PayrollController::class,'updateCell'])->name('payroll.cell.update');Route::get('/payroll/{sheet}/changes',[PayrollController::class,'changes'])->name('payroll.changes');Route::post('/payroll/{sheet}/submit',[PayrollController::class,'submit'])->name('payroll.submit');Route::post('/payroll/{sheet}/approval/request',[ApprovalController::class,'requestOtp'])->name('payroll.approval.request');Route::post('/payroll/{sheet}/approval/confirm',[ApprovalController::class,'confirm'])->name('payroll.approval.confirm');Route::get('/payroll/{sheet}/export/xlsx',[ExportController::class,'excel'])->name('payroll.export.xlsx');Route::get('/payroll/{sheet}/export/pdf',[ExportController::class,'pdf'])->name('payroll.export.pdf');});
